CREATE VIEW `vw_active_exams` AS select `e`.`exam_id` AS `exam_id`,`e`.`exam_title` AS `exam_title`,`e`.`duration_minutes` AS `duration_minutes`,`e`.`randomize_questions` AS `randomize_questions`,`sub`.`subject_name` AS `subject_name`,`sem`.`semester_number` AS `semester_number`,`es`.`schedule_id` AS `schedule_id`,`es`.`exam_date` AS `exam_date`,`es`.`start_time` AS `start_time`,`es`.`end_time` AS `end_time` from (((`exam` `e` join `subject` `sub` on((`sub`.`subject_id` = `e`.`subject_id`))) join `semester` `sem` on((`sem`.`semester_id` = `e`.`semester_id`))) join `exam_schedule` `es` on((`es`.`exam_id` = `e`.`exam_id`))) where ((`e`.`is_published` = true) and (`es`.`is_cancelled` = false) and (`es`.`exam_date` >= curdate()));

CREATE VIEW `vw_exam_total_marks` AS select `eq`.`exam_id` AS `exam_id`,count(`eq`.`question_id`) AS `total_questions`,sum(`q`.`marks`) AS `total_marks` from (`exam_question` `eq` join `question` `q` on((`q`.`question_id` = `eq`.`question_id`))) group by `eq`.`exam_id`;

CREATE VIEW `vw_student_results` AS select `u`.`user_id` AS `user_id`,`u`.`full_name` AS `full_name`,`s`.`enrollment_no` AS `enrollment_no`,`c`.`course_name` AS `course_name`,`sem`.`semester_number` AS `semester_number`,`e`.`exam_title` AS `exam_title`,`es`.`exam_date` AS `exam_date`,`r`.`total_marks_obtained` AS `total_marks_obtained`,`totals`.`total_marks` AS `total_marks`,round(((`r`.`total_marks_obtained` / nullif(`totals`.`total_marks`,0)) * 100),2) AS `percentage`,`r`.`grade` AS `grade`,`r`.`is_published` AS `is_published`,`r`.`published_at` AS `published_at`,`se`.`attempt_number` AS `attempt_number`,`se`.`started_at` AS `started_at`,`se`.`submitted_at` AS `submitted_at` from ((((((((`result` `r` join `student_exam` `se` on((`se`.`student_exam_id` = `r`.`student_exam_id`))) join `student` `s` on((`s`.`student_id` = `se`.`student_id`))) join `user` `u` on((`u`.`user_id` = `s`.`student_id`))) join `exam_schedule` `es` on((`es`.`schedule_id` = `se`.`schedule_id`))) join `exam` `e` on((`e`.`exam_id` = `es`.`exam_id`))) join `semester` `sem` on((`sem`.`semester_id` = `e`.`semester_id`))) join `course` `c` on((`c`.`course_id` = `sem`.`course_id`))) join (select `eq`.`exam_id` AS `exam_id`,sum(`q`.`marks`) AS `total_marks` from (`exam_question` `eq` join `question` `q` on((`q`.`question_id` = `eq`.`question_id`))) group by `eq`.`exam_id`) `totals` on((`totals`.`exam_id` = `e`.`exam_id`)));

CREATE VIEW `vw_student_results_published` AS select `vw_student_results`.`user_id` AS `user_id`,`vw_student_results`.`full_name` AS `full_name`,`vw_student_results`.`enrollment_no` AS `enrollment_no`,`vw_student_results`.`course_name` AS `course_name`,`vw_student_results`.`semester_number` AS `semester_number`,`vw_student_results`.`exam_title` AS `exam_title`,`vw_student_results`.`exam_date` AS `exam_date`,`vw_student_results`.`total_marks_obtained` AS `total_marks_obtained`,`vw_student_results`.`total_marks` AS `total_marks`,`vw_student_results`.`percentage` AS `percentage`,`vw_student_results`.`grade` AS `grade`,`vw_student_results`.`is_published` AS `is_published`,`vw_student_results`.`published_at` AS `published_at`,`vw_student_results`.`attempt_number` AS `attempt_number`,`vw_student_results`.`started_at` AS `started_at`,`vw_student_results`.`submitted_at` AS `submitted_at` from `vw_student_results` where (`vw_student_results`.`is_published` = true);

CREATE VIEW `vw_teacher_subjects` AS select `t`.`teacher_id` AS `teacher_id`,`u`.`full_name` AS `teacher_name`,`d`.`department_name` AS `department_name`,`sub`.`subject_id` AS `subject_id`,`sub`.`subject_name` AS `subject_name`,`c`.`course_name` AS `course_name` from (((((`teaching_assignment` `ta` join `teacher` `t` on((`t`.`teacher_id` = `ta`.`teacher_id`))) join `user` `u` on((`u`.`user_id` = `t`.`teacher_id`))) join `department` `d` on((`d`.`department_id` = `t`.`department_id`))) join `subject` `sub` on((`sub`.`subject_id` = `ta`.`subject_id`))) join `course` `c` on((`c`.`course_id` = `sub`.`course_id`)));

SET FOREIGN_KEY_CHECKS = 1;

DELIMITER $$

CREATE TRIGGER `trg_exam_question_mcq_complete` BEFORE INSERT ON `exam_question` FOR EACH ROW BEGIN
    DECLARE v_type    ENUM('MCQ','THEORY');
    DECLARE v_correct INT DEFAULT 0;
    SELECT question_type INTO v_type FROM question WHERE question_id = NEW.question_id;
    IF v_type = 'MCQ' THEN
        SELECT COUNT(*) INTO v_correct
        FROM option_choice
        WHERE question_id = NEW.question_id AND is_correct = TRUE;
        IF v_correct = 0 THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'MCQ question must have at least one correct option before adding to exam';
        END IF;
    END IF;
END$$

CREATE TRIGGER `trg_enforce_single_correct_ins` BEFORE INSERT ON `option_choice` FOR EACH ROW BEGIN
    DECLARE v_type    ENUM('MCQ','THEORY');
    DECLARE v_correct INT DEFAULT 0;
    IF NEW.is_correct = TRUE THEN
        SELECT question_type INTO v_type FROM question WHERE question_id = NEW.question_id;
        IF v_type = 'MCQ' THEN
            SELECT COUNT(*) INTO v_correct
            FROM option_choice
            WHERE question_id = NEW.question_id AND is_correct = TRUE;
            IF v_correct >= 1 THEN
                SIGNAL SQLSTATE '45000'
                SET MESSAGE_TEXT = 'MCQ question already has a correct option';
            END IF;
        END IF;
    END IF;
END$$

CREATE TRIGGER `trg_enforce_single_correct_upd` BEFORE UPDATE ON `option_choice` FOR EACH ROW BEGIN
    DECLARE v_type    ENUM('MCQ','THEORY');
    DECLARE v_correct INT DEFAULT 0;
    IF NEW.is_correct = TRUE AND OLD.is_correct = FALSE THEN
        SELECT question_type INTO v_type FROM question WHERE question_id = NEW.question_id;
        IF v_type = 'MCQ' THEN
            SELECT COUNT(*) INTO v_correct
            FROM option_choice
            WHERE question_id = NEW.question_id
              AND is_correct  = TRUE
              AND option_id  <> NEW.option_id;
            IF v_correct >= 1 THEN
                SIGNAL SQLSTATE '45000'
                SET MESSAGE_TEXT = 'MCQ question already has a correct option';
            END IF;
        END IF;
    END IF;
END$$

CREATE TRIGGER `trg_auto_grade_ins` BEFORE INSERT ON `result` FOR EACH ROW BEGIN
    DECLARE v_total DECIMAL(6,2) DEFAULT 0;
    DECLARE v_pct   DECIMAL(5,2) DEFAULT 0;
    SELECT COALESCE(SUM(q.marks), 0) INTO v_total
    FROM student_exam se
    JOIN exam_schedule es ON es.schedule_id  = se.schedule_id
    JOIN exam_question  eq ON eq.exam_id     = es.exam_id
    JOIN question q        ON q.question_id  = eq.question_id
    WHERE se.student_exam_id = NEW.student_exam_id;
    IF v_total > 0 THEN
        SET v_pct = (NEW.total_marks_obtained / v_total) * 100;
    END IF;
    SET NEW.grade = CASE
        WHEN v_pct >= 90 THEN 'A+'
        WHEN v_pct >= 80 THEN 'A'
        WHEN v_pct >= 70 THEN 'B'
        WHEN v_pct >= 60 THEN 'C'
        WHEN v_pct >= 50 THEN 'D'
        ELSE 'F'
    END;
END$$

CREATE TRIGGER `trg_result_before_upd` BEFORE UPDATE ON `result` FOR EACH ROW BEGIN
    DECLARE v_total DECIMAL(6,2) DEFAULT 0;
    DECLARE v_pct   DECIMAL(5,2) DEFAULT 0;

    -- Recalculate grade when marks change
    IF NEW.total_marks_obtained <> OLD.total_marks_obtained THEN
        SELECT COALESCE(SUM(q.marks), 0) INTO v_total
        FROM student_exam se
        JOIN exam_schedule es ON es.schedule_id  = se.schedule_id
        JOIN exam_question  eq ON eq.exam_id     = es.exam_id
        JOIN question q        ON q.question_id  = eq.question_id
        WHERE se.student_exam_id = NEW.student_exam_id;
        IF v_total > 0 THEN
            SET v_pct = (NEW.total_marks_obtained / v_total) * 100;
        END IF;
        SET NEW.grade = CASE
            WHEN v_pct >= 90 THEN 'A+'
            WHEN v_pct >= 80 THEN 'A'
            WHEN v_pct >= 70 THEN 'B'
            WHEN v_pct >= 60 THEN 'C'
            WHEN v_pct >= 50 THEN 'D'
            ELSE 'F'
        END;
    END IF;

    -- Stamp published_at when result is first published
    IF NEW.is_published = TRUE AND OLD.is_published = FALSE THEN
        SET NEW.published_at = NOW();
    END IF;
END$$

CREATE TRIGGER `trg_validate_option_ins` BEFORE INSERT ON `scorecard` FOR EACH ROW BEGIN
    DECLARE v_opt_qid INT DEFAULT NULL;
    IF NEW.selected_option_id IS NOT NULL THEN
        SELECT question_id INTO v_opt_qid
        FROM option_choice WHERE option_id = NEW.selected_option_id;
        IF v_opt_qid <> NEW.question_id THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Option does not belong to the specified question';
        END IF;
    END IF;
END$$

CREATE TRIGGER `trg_validate_option_upd` BEFORE UPDATE ON `scorecard` FOR EACH ROW BEGIN
    DECLARE v_opt_qid INT DEFAULT NULL;
    IF NEW.selected_option_id IS NOT NULL
       AND (OLD.selected_option_id IS NULL
            OR NEW.selected_option_id <> OLD.selected_option_id) THEN
        SELECT question_id INTO v_opt_qid
        FROM option_choice WHERE option_id = NEW.selected_option_id;
        IF v_opt_qid <> NEW.question_id THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Option does not belong to the specified question';
        END IF;
    END IF;
END$$

CREATE TRIGGER `trg_validate_scorecard_question` BEFORE INSERT ON `scorecard` FOR EACH ROW BEGIN
    DECLARE v_exam_id   INT DEFAULT NULL;
    DECLARE v_q_in_exam INT DEFAULT 0;
    SELECT es.exam_id INTO v_exam_id
    FROM result r
    JOIN student_exam se  ON se.student_exam_id = r.student_exam_id
    JOIN exam_schedule es ON es.schedule_id     = se.schedule_id
    WHERE r.result_id = NEW.result_id
    LIMIT 1;
    SELECT COUNT(*) INTO v_q_in_exam
    FROM exam_question
    WHERE exam_id = v_exam_id AND question_id = NEW.question_id;
    IF v_q_in_exam = 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Question does not belong to the student exam';
    END IF;
END$$

CREATE TRIGGER `trg_student_role_check` BEFORE INSERT ON `student` FOR EACH ROW BEGIN
    DECLARE v_role ENUM('ADMIN','TEACHER','STUDENT');
    SELECT role INTO v_role FROM user WHERE user_id = NEW.student_id;
    IF v_role <> 'STUDENT' THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'User role must be STUDENT to insert into student table';
    END IF;
END$$

CREATE TRIGGER `trg_se_timestamps` BEFORE UPDATE ON `student_exam` FOR EACH ROW BEGIN
    IF NEW.status = 'IN_PROGRESS' AND OLD.status = 'REGISTERED' THEN
        SET NEW.started_at = NOW();
    END IF;
    IF NEW.status = 'COMPLETED' AND OLD.status = 'IN_PROGRESS' THEN
        SET NEW.submitted_at = NOW();
    END IF;
END$$

CREATE TRIGGER `trg_teacher_role_check` BEFORE INSERT ON `teacher` FOR EACH ROW BEGIN
    DECLARE v_role ENUM('ADMIN','TEACHER','STUDENT');
    SELECT role INTO v_role FROM user WHERE user_id = NEW.teacher_id;
    IF v_role <> 'TEACHER' THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'User role must be TEACHER to insert into teacher table';
    END IF;
END$$

CREATE TRIGGER `trg_prevent_role_change` BEFORE UPDATE ON `user` FOR EACH ROW BEGIN
    IF OLD.role <> NEW.role THEN
        IF OLD.role = 'STUDENT' AND EXISTS (
            SELECT 1 FROM student WHERE student_id = OLD.user_id
        ) THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Cannot change role: user has an active student record';
        END IF;
        IF OLD.role = 'TEACHER' AND EXISTS (
            SELECT 1 FROM teacher WHERE teacher_id = OLD.user_id
        ) THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Cannot change role: user has an active teacher record';
        END IF;
    END IF;
END$$

CREATE PROCEDURE `sp_enroll_student`(
    IN p_student_id  INT,
    IN p_schedule_id INT
)
BEGIN
    DECLARE v_cnt INT DEFAULT 0;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    START TRANSACTION;

        -- Lock the rows first to prevent race condition
        SELECT COUNT(*) INTO v_cnt
        FROM   student_exam
        WHERE  student_id  = p_student_id
          AND  schedule_id = p_schedule_id
        FOR UPDATE;

        IF v_cnt > 0 THEN
            ROLLBACK;
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Student already registered for this schedule';
        ELSE
            INSERT INTO student_exam (student_id, schedule_id)
            VALUES (p_student_id, p_schedule_id);
        END IF;

    COMMIT;
END$$

CREATE PROCEDURE `sp_publish_results`(IN p_exam_id INT)
BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    START TRANSACTION;
        UPDATE result r
        JOIN   student_exam se  ON se.student_exam_id = r.student_exam_id
        JOIN   exam_schedule es ON es.schedule_id     = se.schedule_id
        SET    r.is_published = TRUE
        WHERE  es.exam_id     = p_exam_id
          AND  r.is_published = FALSE;
    COMMIT;
END$$

CREATE PROCEDURE `sp_submit_exam`(
    IN  p_student_exam_id INT,
    OUT p_verdict         VARCHAR(10)
)
BEGIN
    DECLARE v_obtained DECIMAL(6,2) DEFAULT 0;
    DECLARE v_passing  DECIMAL(5,2) DEFAULT 0;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        SET p_verdict = 'ERROR';
        RESIGNAL;
    END;

    START TRANSACTION;

        -- Mark attempt COMPLETED (fires trg_se_timestamps)
        UPDATE student_exam
        SET    status = 'COMPLETED'
        WHERE  student_exam_id = p_student_exam_id;

        -- Get passing threshold for this exam
        SELECT e.passing_marks INTO v_passing
        FROM   student_exam se
        JOIN   exam_schedule es ON es.schedule_id = se.schedule_id
        JOIN   exam e           ON e.exam_id       = es.exam_id
        WHERE  se.student_exam_id = p_student_exam_id;

        -- Sum marks from scorecard (via result FK — result inserted below)
        -- NOTE: scorecard rows are inserted BEFORE calling sp_submit_exam.
        --       They reference a result_id that must already exist.
        --       If result row doesn't exist yet, sum returns 0 and
        --       the INSERT below creates it with correct v_obtained.
        SELECT COALESCE(SUM(sc.marks_obtained), 0) INTO v_obtained
        FROM   scorecard sc
        JOIN   result r ON r.result_id = sc.result_id
        WHERE  r.student_exam_id = p_student_exam_id;

        -- Insert or update result (grade auto-set by trg_auto_grade_ins)
        INSERT INTO result (student_exam_id, total_marks_obtained)
        VALUES (p_student_exam_id, v_obtained)
        ON DUPLICATE KEY UPDATE total_marks_obtained = v_obtained;

        SET p_verdict = IF(v_obtained >= v_passing, 'PASS', 'FAIL');

    COMMIT;
END$$

DELIMITER ;
